package com.abyssia.environment;

import net.minecraft.world.phys.Vec3;

/**
 * One natural current: a stream of water flowing from {@code start} to {@code end} through a capsule of horizontal radius
 * {@code radius} and vertical half-height {@code height} (a sphere when start == end). Generated by {@link NaturalCurrents}.
 */
public record NaturalCurrent(Type type, Vec3 start, Vec3 end, Vec3 direction, float strength, float radius, float height)
{
    public enum Type
    {
        WEAK(0.2f, 0.35f),
        NORMAL(0.4f, 0.7f),
        STRONG(0.7f, 1.0f);

        public final float minStrength, maxStrength;

        Type(float minStrength, float maxStrength)
        {
            this.minStrength = minStrength;
            this.maxStrength = maxStrength;
        }
    }

    public Vec3 center()
    {
        return start.add(end).scale(0.5);
    }

    public double length()
    {
        return start.distanceTo(end);
    }

    /** 1 on the axis, smoothly down to 0 at the capsule's edge, 0 outside. */
    public float falloff(double x, double y, double z)
    {
        double ax = end.x - start.x, ay = end.y - start.y, az = end.z - start.z;
        double lenSq = ax * ax + ay * ay + az * az;
        double t = lenSq < 1.0E-6 ? 0.0 : ((x - start.x) * ax + (y - start.y) * ay + (z - start.z) * az) / lenSq;
        t = Math.max(0.0, Math.min(1.0, t));
        double dx = x - (start.x + ax * t), dy = y - (start.y + ay * t), dz = z - (start.z + az * t);
        double n = (dx * dx + dz * dz) / (radius * radius) + dy * dy / (height * height);
        if (n >= 1.0) return 0f;
        double f = 1.0 - n;
        return (float) (f * f);
    }

    /** Distance from the point to the axis segment, ignoring the radius (for coarse range checks). */
    public double axisDistance(double x, double y, double z)
    {
        double ax = end.x - start.x, ay = end.y - start.y, az = end.z - start.z;
        double lenSq = ax * ax + ay * ay + az * az;
        double t = lenSq < 1.0E-6 ? 0.0 : Math.max(0.0, Math.min(1.0, ((x - start.x) * ax + (y - start.y) * ay + (z - start.z) * az) / lenSq));
        double dx = x - (start.x + ax * t), dy = y - (start.y + ay * t), dz = z - (start.z + az * t);
        return Math.sqrt(dx * dx + dy * dy + dz * dz);
    }
}
